    select * from dc_stray_animal


            and stray_category = #{stray_category}


            and stray_name = #{stray_name}


            and stray_shelter_addr LIKE '%' || #{sido} || '%'


            and stray_shelter_addr LIKE '%' || #{gungu} || '%'


            AND stray_status = #{stray_status}





